// A deterministic event-loop simulator scaffold.
const macro = []; // task queue
const micro = []; // microtask queue
const log = [];
function setTimeout0(fn) { macro.push(fn); }      // schedule a macrotask
function queueMicro(fn) { micro.push(fn); }        // schedule a microtask
function drainMicro() { while (micro.length) micro.shift()(); }

